package fpv.render;

import arc.*;import arc.graphics.*;import arc.graphics.g2d.*;import arc.mock.*;import arc.util.*;import mindustry.*;import mindustry.content.*;import mindustry.core.*;import mindustry.game.*;import mindustry.gen.*;import mindustry.world.*;import mindustry.world.blocks.production.*;import fpv.construction.*;import java.util.*;

/** Installed 160.7 definitions and renderer invariants; mock GL, physical acceptance separate. */
public final class ChemicalModelNativeTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static class Tex extends Texture{Tex(){super();width=height=64;}}
 static void pose(Building b,float t){b.enabled=true;b.efficiency=1;if(b instanceof SolidPump.SolidPumpBuild p){p.pumpTime=t;p.warmup=1;p.lastPump=.1f;p.validTiles=1;p.boost=1;}else{var c=(GenericCrafter.GenericCrafterBuild)b;c.progress=.5f;c.warmup=1;c.totalProgress=t;}}
 static void inputs(Building b){if(b.items!=null)b.items.clear();for(var c:b.block.consumers){if(c instanceof mindustry.world.consumers.ConsumeItems items)for(var s:items.items)b.items.set(s.item,Math.min(b.block.itemCapacity,s.amount*3));if(c instanceof mindustry.world.consumers.ConsumeLiquid liquid)b.liquids.set(liquid.liquid,b.block.liquidCapacity*.7f);}if(b.power!=null)b.power.status=1;}
 static boolean output(Building b){if(b.block instanceof SolidPump p)return b.liquids.get(p.result)>0;var c=(GenericCrafter)b.block;if(c.outputItems!=null)for(var s:c.outputItems)if(b.items.get(s.item)>0)return true;if(c.outputLiquids!=null)for(var s:c.outputLiquids)if(b.liquids.get(s.liquid)>0)return true;return false;}
 public static void main(String[] args)throws Exception{
  ArcNativesLoader.load();mindustry.graphics.CacheLayer.init();Core.app=new MockApplication();Core.files=new MockFiles();Core.settings=new MockSettings();Core.bundle=I18NBundle.createEmptyBundle();Core.audio=new MockAudio();Core.graphics=new MockGraphics();Core.gl=new MockGL20();Vars.headless=true;Vars.tree=new FileTree();Vars.content=new ContentLoader();Vars.content.createBaseContent();Vars.state=new GameState();Vars.net=new mindustry.net.Net(null);Groups.init();Vars.world=new World();Vars.world.tiles=new Tiles(128,96);Vars.world.setGenerating(true);Vars.world.tiles.fill();Vars.indexer=new mindustry.ai.BlockIndexer();Groups.resize(0,0,1024,768);Time.clear();Time.setDeltaProvider(()->1);Vars.content.init();Vars.state.set(GameState.State.playing);
  var pix=new Pixmap(32,32);pix.fill(0xa0a0a0ff);var region=new TextureAtlas.AtlasRegion(new Tex(),0,0,32,32);region.name="chemical-fixture";Core.atlas=new TextureAtlas(){@Override public PixmapRegion getPixmap(TextureAtlas.AtlasRegion a){return new PixmapRegion(pix);}};Core.atlas.addRegion("white",region);
  Block[] types={Blocks.cryofluidMixer,Blocks.melter,Blocks.sporePress,Blocks.coalCentrifuge,Blocks.cultivator,Blocks.waterExtractor,Blocks.oilExtractor,Blocks.pulverizer};int[] sizes={2,1,2,2,2,2,3,1};
  check(!ChemicalModelRenderer.supports(Blocks.kiln)&&!ChemicalModelRenderer.supports(Blocks.incinerator)&&!ChemicalModelRenderer.supports(Blocks.ventCondenser),"exact scope leaves previous models, optional incinerator and Erekir unchanged");
  for(int i=0;i<types.length;i++){var b=types[i];check(b.size==sizes[i],"installed footprint");check(i==5?b instanceof SolidPump:i==6?b instanceof Fracker:b instanceof GenericCrafter,"installed native class");b.region=b.fullIcon=region;System.out.println("A2-16f native "+b.name+" size="+b.size+" capacity="+b.liquidCapacity+" physicalHeight="+fpv.net.HeadlessGeometry.heightFor(b));}
  check(Blocks.cultivator instanceof AttributeCrafter,"cultivator is native attribute crafter");check(((SolidPump)Blocks.waterExtractor).result==Liquids.water&&((SolidPump)Blocks.oilExtractor).result==Liquids.oil,"real pump products");check(((GenericCrafter)Blocks.pulverizer).craftTime==40&&((Fracker)Blocks.oilExtractor).itemUseTime==60,"installed production periods");
  var renderer=new ChemicalModelRenderer();var batch=new NativeAtlasMesh.Builder(false);long id=100;
  try{
   for(var p:ChemicalModelProfile.values())for(int lod=0;lod<3;lod++){
    var m=ChemicalModelGeometry.model(p,types[p.ordinal()].size,lod);check(m==ChemicalModelGeometry.model(p,types[p.ordinal()].size,lod),"shared immutable templates");int count=0;
    for(var a:new float[][]{m.body(),m.lining(),m.rotor(),m.piston(),m.arm(),m.fluid(),m.accent()}){count+=a.length/8;check(a.length%24==0,"triangle stream");for(int i=0;i<a.length;i+=8){for(int j=0;j<8;j++)check(Float.isFinite(a[i+j]),"finite template");boolean fluid=a==m.fluid();check(Math.abs(a[i])<=(fluid?1:.501)&&Math.abs(a[i+2])<=(fluid?1:.501)&&a[i+1]>=(a==m.arm()?-.04:0)&&a[i+1]<=1,"normalized parts bounded");check(fluid||a[i+6]<0||a[i+6]<=1&&a[i+7]>=0&&a[i+7]<=1,"safe material template");}}
    check(count<3500&&(lod<2||count==30),"bounded near and ten-triangle far hull");
   }
   for(int floor:new int[]{0,1,3,4,5})for(int t=0;t<8;t++)for(int rotation=0;rotation<4;rotation++){
    var b=AdvancedLogisticsNativeTest.put(new LayerBuildingAdapter(null),id++,12+rotation*24,10+t*9,floor,types[t],rotation);inputs(b);if(b.liquids!=null){b.liquids.set(Liquids.water,b.block.liquidCapacity*.4f);b.liquids.set(Liquids.cryofluid,b.block.liquidCapacity*.7f);b.liquids.set(Liquids.slag,b.block.liquidCapacity*.4f);b.liquids.set(Liquids.oil,b.block.liquidCapacity*.3f);}
    pose(b,21);check(ChemicalModelRenderer.activity(b)==1,"real native active state");float clock=ChemicalModelRenderer.clock(b);Time.time+=500;check(clock==ChemicalModelRenderer.clock(b),"render clock is native, not global time");
    for(float time:new float[]{0,9,28})for(float distance:new float[]{0,900,10000}){
     pose(b,time);var state=LogisticsModelNativeTest.state(b);float oldClock=ChemicalModelRenderer.clock(b);batch.clear();float h=fpv.net.HeadlessGeometry.heightFor(b.block),base=floor*1.4f;check(renderer.render(b,batch,0,base,0,b.block.size,h,distance),"XYZ/rotation/LOD native rendering");var v=LogisticsModelNativeTest.vertices(batch);check(v.length>0,"submitted geometry");for(int i=0;i<v.length;i+=9){for(int j=0;j<9;j++)check(Float.isFinite(v[i+j]),"finite animated stream");check(Math.abs(v[i])<=b.block.size*.501f&&Math.abs(v[i+2])<=b.block.size*.501f&&v[i+1]>=base-.0001f&&v[i+1]<=base+h+.005f,"animation within unchanged footprint and physical height");check(v[i+7]>=0&&v[i+7]<=.5f&&v[i+8]>=0&&v[i+8]<=.5f,"native/white atlas containment");}check(Arrays.equals(state,LogisticsModelNativeTest.state(b))&&oldClock==ChemicalModelRenderer.clock(b),"render read-only including native unsaved pump clock");
    }
    if(t==6){
     // Check actual submitted rod vertices against the beam transform, including roll's sign.
     for(float time:new float[]{0,9,28}){pose(b,time);batch.clear();float h=fpv.net.HeadlessGeometry.heightFor(b.block),base=floor*1.4f;renderer.render(b,batch,0,base,0,b.block.size,h,0);var v=LogisticsModelNativeTest.vertices(batch);var g=ChemicalModelGeometry.model(ChemicalModelProfile.OIL,b.block.size,0);int start=(g.body().length+g.lining().length+g.arm().length)/8;float top=Float.NEGATIVE_INFINITY;for(int i=start;i<start+g.piston().length/8;i++)top=Math.max(top,v[i*9+1]);var axis=new double[9];SpriteExtrusionGeometry.basis(90,0,-12+24*ChemicalModelRenderer.stroke(b),axis);check(Math.abs(top-(base+h*.71f-.325f*b.block.size*axis[1]))<.00001,"pump rod stays attached to actual pitched beam in both directions");}
    }
    b.enabled=false;check(ChemicalModelRenderer.activity(b)==0,"disabled machine rests");b.enabled=true;b.efficiency=0;check(ChemicalModelRenderer.activity(b)==0,"no power/input rests");b.efficiency=1;
    if(b instanceof SolidPump.SolidPumpBuild pump){pump.lastPump=0;check(ChemicalModelRenderer.activity(b)==0,"no pumping/substrate cannot animate at full power");}
    if(b.liquids!=null){b.liquids.clear();check(ChemicalModelRenderer.fill(b,Liquids.water)==0,"empty tank");b.liquids.set(Liquids.water,b.block.liquidCapacity*.25f);b.liquids.set(Liquids.oil,b.block.liquidCapacity*.8f);check(ChemicalModelRenderer.fill(b,Liquids.water)==.25f&&ChemicalModelRenderer.fill(b,Liquids.oil)==.8f,"explicit liquid identity, never last-current substitution");b.liquids.set(Liquids.water,Float.NaN);check(ChemicalModelRenderer.fill(b,Liquids.water)==0,"non-finite safe fallback");}
   }
   for(int t=0;t<8;t++){
    var b=new LayerBuildingAdapter(null).create(id++,12+t*5,86,3,types[t],Team.sharded,0);inputs(b);if(b.liquids!=null){if(b.block instanceof GenericCrafter c&&c.outputLiquids!=null)for(var s:c.outputLiquids)b.liquids.set(s.liquid,0);if(b.block instanceof SolidPump p)b.liquids.set(p.result,0);}pose(b,0);boolean produced=false;for(int tick=0;tick<500&&!produced;tick++){Time.delta=1;b.updateTile();produced=output(b);}check(produced,"native updateTile produces "+b.block.name);
    var state=LogisticsModelNativeTest.state(b);float time=ChemicalModelRenderer.clock(b);long builds=renderer.builds();for(int frame=0;frame<25;frame++){batch.clear();renderer.render(b,batch,0,4.2f,0,b.block.size,fpv.net.HeadlessGeometry.heightFor(b.block),0);}check(Arrays.equals(state,LogisticsModelNativeTest.state(b))&&time==ChemicalModelRenderer.clock(b),"renderer cannot craft, pump, consume or advance clocks");check(builds==renderer.builds(),"no frame/instance regeneration");
   }
   var pump=new LayerBuildingAdapter(null).create(id++,60,86,3,Blocks.waterExtractor,Team.sharded,0);var liquids=pump.liquids;pose(pump,1);pump.liquids=null;check(ChemicalModelRenderer.fill(pump,Liquids.water)==0,"missing module fallback");batch.clear();check(renderer.render(pump,batch,0,4.2f,0,2,1.26f,0),"missing liquid module still renders safely");pump.liquids=liquids;
   check(renderer.entries()==8&&renderer.builds()==8&&renderer.bytes()<2_000_000,"bounded per-type cache");System.out.println("ChemicalModelNativeTest: "+checks+" native definitions/XYZ/UV/LOD/animation/liquid/read-only/production/cache checks PASS; mock GL");
  }finally{renderer.clear();batch.dispose();pix.dispose();}
 }
}
